const body = $input.first().json || {};
const media = Array.isArray(body.data) ? body.data : [];
const now = new Date();
const todayStart = new Date(now);
todayStart.setHours(0, 0, 0, 0);
const yesterdayStart = new Date(todayStart);
yesterdayStart.setDate(yesterdayStart.getDate() - 1);
const tomorrowStart = new Date(todayStart);
tomorrowStart.setDate(tomorrowStart.getDate() + 1);

const inWindow = media.filter(item => {
  if (!item.timestamp) return true;
  const published = new Date(item.timestamp);
  return published >= yesterdayStart && published < tomorrowStart;
});
const selected = inWindow.length > 0 ? inWindow : media.slice(0, 10);

return selected.map(item => ({
  json: {
    instagram_media_id: item.id,
    media: item,
    collected_at: now.toISOString(),
    fallback_window: inWindow.length === 0
  }
}));

const mediaItem = $('SYS_SplitMediaItems').item.json;
const media = mediaItem.media || {};
const insightsPayload = $('IG_ReadMediaInsights').item.json || {};
const commentsPayload = $input.first().json || {};
const collectedAt = mediaItem.collected_at || new Date().toISOString();

function metricValue(payload, names) {
  const rows = Array.isArray(payload.data) ? payload.data : [];
  for (const name of names) {
    const row = rows.find(item => item.name === name);
    const value = row?.values?.[0]?.value;
    if (value !== undefined && value !== null) return Number(value);
  }
  return null;
}

function cleanText(value) {
  return String(value || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

const comments = Array.isArray(commentsPayload.data) ? commentsPayload.data : [];
const normalizedComments = comments.map(comment => ({
  instagram_comment_id: comment.id,
  instagram_media_id: media.id,
  comment_text: cleanText(comment.text),
  author_username: comment.username || null,
  commented_at: comment.timestamp || null,
  like_count: comment.like_count ?? null
}));

const stopWords = new Set(['the','and','for','with','you','your','this','that','are','was','not','but','from','have','has','will','can','как','что','это','для','или','если','меня','только','очень','надо','нужно','без','его','она','они','мы','вы','не','на','в','и','а','но']);
const counts = new Map();
for (const comment of normalizedComments) {
  for (const word of comment.comment_text.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, ' ').split(/\s+/)) {
    if (word.length < 4 || stopWords.has(word)) continue;
    counts.set(word, (counts.get(word) || 0) + 1);
  }
}
const repeated = Array.from(counts.entries())
  .filter(([, count]) => count > 1)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([phrase, count]) => ({ phrase, count }));

const metrics = {
  reach: metricValue(insightsPayload, ['reach']),
  views: metricValue(insightsPayload, ['views', 'plays', 'impressions']),
  likes: metricValue(insightsPayload, ['likes']) ?? (media.like_count ?? null),
  comments: metricValue(insightsPayload, ['comments']) ?? (media.comments_count ?? normalizedComments.length),
  saves: metricValue(insightsPayload, ['saved', 'saves']),
  shares: metricValue(insightsPayload, ['shares']),
  total_interactions: metricValue(insightsPayload, ['total_interactions'])
};

const score = (metrics.reach || 0) + (metrics.views || 0) + ((metrics.likes || 0) * 3) + ((metrics.comments || 0) * 5) + ((metrics.saves || 0) * 6) + ((metrics.shares || 0) * 6);

return [{
  json: {
    instagram_media_id: media.id,
    media_type: media.media_type || null,
    caption: media.caption || null,
    permalink: media.permalink || null,
    published_at: media.timestamp || null,
    collected_at: collectedAt,
    fallback_window: mediaItem.fallback_window || false,
    metrics,
    comments: normalizedComments,
    repeated_phrase_candidates: repeated,
    insights_available: Array.isArray(insightsPayload.data),
    score,
    dry_run: true
  }
}];

const items = $input.all().map(item => item.json || {});
const mediaItems = items.filter(item => item.instagram_media_id);
const now = new Date().toISOString();

function n(value) {
  return value === null || value === undefined ? 0 : Number(value);
}

function text(value, max = 90) {
  const clean = String(value || 'untitled').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
  return clean.length > max ? clean.slice(0, max - 3) + '...' : clean;
}

function contentLine(item) {
  const m = item.metrics || {};
  return '- ' + text(item.caption || item.permalink || item.instagram_media_id) + ' | score ' + n(item.score) + ' | likes ' + n(m.likes) + ', comments ' + n(m.comments) + ', saves ' + n(m.saves) + ', reach ' + n(m.reach) + ', views ' + n(m.views);
}

function escapeTelegramMarkdown(value) {
  return String(value).replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
}

const totals = mediaItems.reduce((acc, item) => {
  const m = item.metrics || {};
  acc.likes += n(m.likes);
  acc.comments += n(m.comments);
  acc.saves += n(m.saves);
  acc.reach += n(m.reach);
  acc.views += n(m.views);
  acc.comment_rows += Array.isArray(item.comments) ? item.comments.length : 0;
  acc.insights += item.insights_available ? 1 : 0;
  return acc;
}, { likes: 0, comments: 0, saves: 0, reach: 0, views: 0, comment_rows: 0, insights: 0 });

const top = [...mediaItems].sort((a, b) => n(b.score) - n(a.score)).slice(0, 3);
const under = [...mediaItems].sort((a, b) => n(a.score) - n(b.score)).slice(0, 2);
const phraseCounts = new Map();
for (const item of mediaItems) {
  for (const phrase of item.repeated_phrase_candidates || []) {
    phraseCounts.set(phrase.phrase, (phraseCounts.get(phrase.phrase) || 0) + n(phrase.count));
  }
}
const themes = Array.from(phraseCounts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([phrase, count]) => phrase + ' (' + count + ')');
const best = top[0];
const bestReason = best ? 'Best performer: ' + text(best.caption || best.permalink || best.instagram_media_id) + '.' : 'No media returned.';
const underReason = under.length ? 'Review weak hooks/CTA for: ' + under.map(item => text(item.caption || item.permalink || item.instagram_media_id, 45)).join('; ') + '.' : 'No underperformer yet.';
const marketSignal = themes.length ? 'Repeated comment language: ' + themes.join(', ') + '.' : 'Not enough repeated comment language yet.';
const nextAction = best ? 'Create the next post from the best-performing topic and ask for one concrete parent example.' : 'Publish one clear question-led post, then re-run analytics.';
const windowLabel = mediaItems.some(item => item.fallback_window) ? 'latest media fallback' : 'yesterday + today';

const lines = [
  'BrainCoach Instagram Analytics MVP-1 DRY RUN',
  now,
  '',
  'Window: ' + windowLabel,
  '- media collected: ' + mediaItems.length,
  '- media with insights: ' + totals.insights,
  '- comment rows read: ' + totals.comment_rows,
  '- likes: ' + totals.likes,
  '- comments: ' + totals.comments,
  '- saves: ' + totals.saves,
  '- reach: ' + totals.reach,
  '- views: ' + totals.views,
  '',
  '1. Top content',
  ...(top.length ? top.map(contentLine) : ['- none']),
  '',
  '2. What performed best',
  '- ' + bestReason,
  '',
  '3. What underperformed',
  ...(under.length ? under.map(contentLine) : ['- none']),
  '- ' + underReason,
  '',
  '4. Repeated comment themes',
  '- ' + (themes.length ? themes.join(', ') : 'none'),
  '',
  '5. Possible market signals',
  '- ' + marketSignal,
  '',
  '6. Recommended next content action',
  '- ' + nextAction,
  '',
  'Boundary: dry-run/read-only. No DB writes. No public Instagram actions. No comments/replies publishing. No bgs_core writes.'
];

return [{
  json: {
    report_text: escapeTelegramMarkdown(lines.join('\n')),
    dry_run: true,
    media_count: mediaItems.length,
    comment_rows: totals.comment_rows
  }
}];
